import React, { useState, useMemo, useEffect } from 'react';

// --- SVG Icon Components ---
const InfoIcon = () => <svg style={{ color: '#6b7280' }} xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg>;
const AddIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>;
const EditIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>;
const DeleteIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>;
const SaveIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ marginRight: '8px' }}><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path><polyline points="17 21 17 13 7 13 7 21"></polyline><polyline points="7 3 7 8 15 8"></polyline></svg>;


export default function WDPerStudentPerActivityAllocationTab({ subject, sourceOfTruthData }) {
    // --- Styles from Prompt ---
    const styles = {
        panel: { backgroundColor: "#ffffff", borderRadius: "8px", boxShadow: "0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06)", padding: "32px", marginBottom: "32px" },
        h2: { fontSize: "20px", fontWeight: "600", color: "#111827", marginBottom: "8px" },
        headerContainer: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' },
        titleContainer: { display: 'flex', alignItems: 'center', gap: '12px' },
        button: { primary: { backgroundColor: "#111827", color: "white", padding: "10px 24px", borderRadius: "6px", fontWeight: "600", border: "none", cursor: "pointer", display: 'flex', alignItems: 'center' }, add: { backgroundColor: "#111827", color: "white", padding: "8px 16px", borderRadius: "6px", fontWeight: "600", border: "none", cursor: "pointer", display: 'flex', alignItems: 'center', gap: '8px' } },
        tabContainer: { borderBottom: "1px solid #e5e7eb", marginBottom: "24px", display: 'flex' },
        tab: { base: { padding: "12px 4px", marginRight: "24px", borderBottom: "2px solid transparent", fontSize: "14px", fontWeight: "600", cursor: "pointer", backgroundColor: "transparent", borderTop: "none", borderLeft: "none", borderRight: "none" }, active: { color: "#2563eb", borderBottom: "2px solid #2563eb" }, inactive: { color: "#6b7280" } },
        table: { base: { width: "100%", borderCollapse: "collapse" }, thead: { backgroundColor: "#f9fafb" }, th: { padding: "12px 16px", textAlign: "left", fontSize: "12px", fontWeight: "600", color: "#6b7280", textTransform: "uppercase", letterSpacing: "0.05em", borderBottom: '1px solid #e5e7eb' }, tr: { borderBottom: "1px solid #e5e7eb" }, td: { padding: "12px 16px", fontSize: "14px", verticalAlign: "middle" } },
        inputField: { width: "95%", padding: "6px 8px", border: "1px solid #d1d5db", borderRadius: "6px", boxSizing: 'border-box' },
        iconButton: { background: 'none', border: 'none', cursor: 'pointer', padding: '4px', margin: '0 4px' },
        summaryRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: '24px', marginTop: '24px', borderTop: '1px solid #e5e7eb' },
        summaryLabel: { fontSize: '14px', color: '#374151' },
        summaryValue: { fontSize: '16px', fontWeight: 'bold', color: '#111827' },
        footer: { display: 'flex', justifyContent: 'flex-end', marginTop: '32px' }
    };

    // --- Calculation Logic & Constants from Prompt ---
    const C = { // Staff Member Allocation Constants
        SUM_BaseAllocation_PerStudent: { value: 0.002 },
        WorkloadMultiplier: { value: 1 },
        Activity1_HoursPerGroup: { value: 0.1 },
        SUM_Activity1_AllocationWeight: { value: 0.5 },
        Activity2_HoursPerGroup: { value: 0.15 },
        SUM_Activity2_AllocationWeight: { value: 0.4 },
        Activity3_HoursPerGroup: { value: 0.2 },
        SUM_Activity3_AllocationWeight: { value: 0.3 }
    };

    const Coord_C = { // Coordinator Allocation Constants
        Coord_NumStudents: { value: 2.0 },
        Coord_SUM_BaseAllocation_PerStudent: { value: 0.2 },
        Coord_WorkloadMultiplier: { value: 1.0 },
        Coord_NumGroups_Activity1: { value: 150.0 },
        Coord_Activity1_HoursPerGroup: { value: 0.1 },
        Coord_SUM_Activity1_AllocationWeight: { value: 0.5 },
        Coord_NumGroups_Activity2: { value: 5.0 },
        Coord_Activity2_HoursPerGroup: { value: 0.15 },
        Coord_SUM_Activity2_AllocationWeight: { value: 0.4 },
        Coord_NumGroups_Activity3: { value: 2.0 },
        Coord_Activity3_HoursPerGroup: { value: 0.2 },
        Coord_SUM_Activity3_AllocationWeight: { value: 0.3 }
    };

    function calculateStaffAllocation(staff, constants) {
        const { students, groups } = staff;
        const perStudentPart = (students / 25) * constants.SUM_BaseAllocation_PerStudent.value;
        const activity1Part = constants.WorkloadMultiplier.value * ((groups['activity-1'] || 0) * constants.Activity1_HoursPerGroup.value * constants.SUM_Activity1_AllocationWeight.value);
        const activity2Part = (groups['activity-2'] || 0) * constants.Activity2_HoursPerGroup.value * constants.SUM_Activity2_AllocationWeight.value;
        const activity3Part = (groups['activity-3'] || 0) * constants.Activity3_HoursPerGroup.value * constants.SUM_Activity3_AllocationWeight.value;
        return (perStudentPart + activity1Part + activity2Part + activity3Part); // Return as decimal
    }

    const coordinatorAllocation = useMemo(() => {
        const C = Coord_C;
        const part1 = (C.Coord_NumStudents.value / 25) * C.Coord_SUM_BaseAllocation_PerStudent.value;
        const part2 = C.Coord_WorkloadMultiplier.value * (C.Coord_NumGroups_Activity1.value * C.Coord_Activity1_HoursPerGroup.value * C.Coord_SUM_Activity1_AllocationWeight.value);
        const part3 = C.Coord_NumGroups_Activity2.value * C.Coord_Activity2_HoursPerGroup.value * C.Coord_SUM_Activity2_AllocationWeight.value;
        const part4 = C.Coord_NumGroups_Activity3.value * C.Coord_Activity3_HoursPerGroup.value * C.Coord_SUM_Activity3_AllocationWeight.value;
        return (part1 + part2 + part3 + part4); // Return as decimal
    }, []);

    // --- State Management ---
    const [rolesData, setRolesData] = useState([
        { id: "role-a", name: "Lecturer", activities: [{ id: "activity-1", name: "Activity 1 - Lecture" }, { id: "activity-2", name: "Activity 2 - Tutorial" }, { id: "activity-3", name: "Activity 3 - Workshop" }], staffAllocations: [{ id: "staff-1", name: "Tom", students: 30, groups: { "activity-1": 2, "activity-2": 0, "activity-3": 0 } }, { id: "staff-2", name: "Usha", students: 30, groups: { "activity-1": 2, "activity-2": 0, "activity-3": 0 } }, { id: "staff-3", name: "Victoria", students: 40, groups: { "activity-1": 0, "activity-2": 3, "activity-3": 0 } }] },
        { id: "role-b", name: "Exam marker", activities: [{ id: "activity-1", name: "Marking" }], staffAllocations: [] },
        { id: "role-c", name: "Tutor", activities: [{ id: "activity-1", name: "Tutorial" }], staffAllocations: [] },
        { id: "role-d", name: "Lab supervisor", activities: [{ id: "activity-1", name: "Lab Session" }], staffAllocations: [] }
    ]);
    const [activeTab, setActiveTab] = useState('role-a');

     // 1. ADD STATE TO HOLD VALIDATION ERRORS
    const [errors, setErrors] = useState({});

    // 2. ADD useEffect TO RUN VALIDATION LOGIC
    useEffect(() => {
        const newErrors = {};

        // Validation 1: Total Number of Students
        if (sourceOfTruthData?.totalStudents > 0) {
            const currentTotalStudents = rolesData.reduce((total, role) => 
                total + role.staffAllocations.reduce((subTotal, staff) => subTotal + (staff.students || 0), 0), 0);

            if (currentTotalStudents > sourceOfTruthData.totalStudents) {
                newErrors.students = `Error: The total number of allocated students (${currentTotalStudents}) exceeds the subject total of ${sourceOfTruthData.totalStudents} defined in the 'Per-student Allocation' tab.`;
            }
        }

        // Validation 2: Number of Groups per Activity
        const groupErrors = {};
        rolesData.forEach(role => {
            role.activities.forEach((activity, index) => {
                // Find the corresponding activity from the source data (matching by index as a fallback)
                const sourceActivity = sourceOfTruthData?.activityGroups[index];
                if (sourceActivity) {
                    const allocatedGroups = role.staffAllocations.reduce((sum, staff) => sum + (staff.groups[activity.id] || 0), 0);

                    if (allocatedGroups > sourceActivity.numberOfGroups) {
                        groupErrors[activity.id] = `For "${sourceActivity.name}", the allocated groups (${allocatedGroups}) exceed the total of ${sourceActivity.numberOfGroups} defined in the 'Activity Allocation' tab.`;
                    }
                }
            });
        });

        if (Object.keys(groupErrors).length > 0) {
            newErrors.groups = groupErrors;
        }

        setErrors(newErrors);

    }, [rolesData, sourceOfTruthData]);

    const activeRole = useMemo(() => rolesData.find(role => role.id === activeTab), [rolesData, activeTab]);

    // --- Event Handlers ---
    const handleInputChange = (staffId, field, value, activityId = null) => {
        const numericValue = value === '' ? '' : Math.max(0, parseFloat(value)); // Enforce non-negative validation

        setRolesData(currentRoles => currentRoles.map(role => {
            if (role.id === activeTab) {
                const updatedAllocations = role.staffAllocations.map(staff => {
                    if (staff.id === staffId) {
                        if (field === 'groups' && activityId) {
                            return { ...staff, groups: { ...staff.groups, [activityId]: numericValue } };
                        }
                        return { ...staff, [field]: numericValue };
                    }
                    return staff;
                });
                return { ...role, staffAllocations: updatedAllocations };
            }
            return role;
        }));
    };

    const handleAddRow = () => {
        const newStaff = {
            id: `staff-${Date.now()}`,
            name: '',
            students: 0,
            groups: activeRole.activities.reduce((acc, activity) => {
                acc[activity.id] = 0;
                return acc;
            }, {})
        };

        setRolesData(currentRoles => currentRoles.map(role => {
            if (role.id === activeTab) {
                return { ...role, staffAllocations: [...role.staffAllocations, newStaff] };
            }
            return role;
        }));
    };

    const handleDeleteRow = (staffId) => {
        setRolesData(currentRoles => currentRoles.map(role => {
            if (role.id === activeTab) {
                return { ...role, staffAllocations: role.staffAllocations.filter(s => s.id !== staffId) };
            }
            return role;
        }));
    };


    return (
        <div style={styles.panel}>
            <div style={styles.headerContainer}>
                <div style={styles.titleContainer}>
                    <h2 style={styles.h2}>Per-student / Per-activity Allocation</h2>
                    <InfoIcon />
                </div>
                <button style={styles.button.add} onClick={handleAddRow}>
                    <AddIcon /> Add
                </button>
            </div>

            <div style={styles.tabContainer}>
                {rolesData.map(role => (
                    <button
                        key={role.id}
                        onClick={() => setActiveTab(role.id)}
                        style={{ ...styles.tab.base, ...(activeTab === role.id ? styles.tab.active : styles.tab.inactive) }}
                    >
                        {`Role ${role.id.split('-')[1].toUpperCase()} ${role.name}`}
                    </button>
                ))}
            </div>

            <table style={styles.table.base}>
                <thead style={styles.table.thead}>
                    <tr>
                        <th style={styles.table.th}>Actions</th>
                        <th style={styles.table.th}>Staff Member Acting in Role</th>
                        <th style={styles.table.th}>Number of Students</th>
                        {activeRole?.activities.map(activity => (
                            <th key={activity.id} style={styles.table.th}>{`Number of groups for ${activity.name}`}</th>
                        ))}
                        <th style={{...styles.table.th, textAlign: 'right'}}>Allocation</th>
                    </tr>
                </thead>
                <tbody>
                    {activeRole?.staffAllocations.map(staff => (
                        <tr key={staff.id} style={styles.table.tr}>
                            <td style={styles.table.td}>
                                <button style={styles.iconButton}><EditIcon /></button>
                                <button style={styles.iconButton} onClick={() => handleDeleteRow(staff.id)}><DeleteIcon /></button>
                            </td>
                            <td style={styles.table.td}>
                                <input
                                    type="text"
                                    style={styles.inputField}
                                    value={staff.name}
                                    onChange={(e) => handleInputChange(staff.id, 'name', e.target.value)}
                                />
                            </td>
                            <td style={styles.table.td}>
                                <input
                                    type="number"
                                    min="0"
                                    style={styles.inputField}
                                    value={staff.students}
                                    onChange={(e) => handleInputChange(staff.id, 'students', e.target.value)}
                                />
                            </td>
                            {activeRole.activities.map(activity => (
                                <td key={activity.id} style={styles.table.td}>
                                    <input
                                        type="number"
                                        min="0"
                                        style={styles.inputField}
                                        value={staff.groups[activity.id] || 0}
                                        onChange={(e) => handleInputChange(staff.id, 'groups', e.target.value, activity.id)}
                                    />
                                </td>
                            ))}
                            <td style={{ ...styles.table.td, textAlign: 'right', fontWeight: 'bold' }}>
                                {(calculateStaffAllocation(staff, C) * 100).toFixed(1)}%
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>

            <div style={styles.summaryRow}>
                <span style={styles.summaryLabel}>Allocation to Subject Coordinator: {subject?.subjectCoordinator || "Tom"}</span>
                <span style={styles.summaryValue}>{(coordinatorAllocation * 100).toFixed(1)}%</span>
            </div>

            <div style={styles.footer}>
                <button style={styles.button.primary}>
                    <SaveIcon />
                    Save
                </button>
            </div>
        </div>
    );
}
